import {sessionRequest,logout,escapeText as esc} from './account.js';
import {topics,initial,apply,prepare,baseline,unlocked,diagnosticQuestion,unitQuestion,correct,nextSessions,supportFor,SLIDE_COUNT} from './learning-core.js';
import {lessonSlides} from './classroom-content.js';
import {math,rich,fraction,spoken} from './math.js';
const $=s=>document.querySelector(s),root=$('#learning-root');
let user,lang='tr',data,state,revision=0,busy=false,feedback=null,selected='',voice=false,mic=null,local=false,localKey='',page=location.hash.slice(1)||'discover',chatBusy=false,boardMode='lesson',revealed=0,readingToken=0,coachError='',answerFraction=false,pendingDraft=null;
const w=(tr,en)=>lang==='tr'?tr:en,title=id=>topics.find(t=>t.id===id)?.title[lang]||id;
const labels=()=>({discover:w('Keşif atölyesi','Discovery studio'),route:w('Öğrenme rotam','My learning path'),plan:w('Çalışma planım','My study plan'),progress:w('Gelişimim','My progress')});
const notice=text=>{const n=$('#notice');n.textContent=text;n.style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.style.display='none',6000)};
function fmt(n){return Number(n).toLocaleString(lang==='tr'?'tr-TR':'en-US',{maximumFractionDigits:4})}
function date(iso){return new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:state.plan?.zone||'Europe/Istanbul'}).format(new Date(iso))}
function stopSpeech(){readingToken++;if('speechSynthesis'in window)window.speechSynthesis.cancel()}
function speak(text,onend){if(!voice||!('speechSynthesis'in window)){onend?.();return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(spoken(text,lang));u.lang=lang==='tr'?'tr-TR':'en-US';u.rate=.94;if(onend)u.onend=onend;u.onerror=()=>notice(w('Sesli okuma durdu. Tahtadaki adımları yazılı takip edebilirsin.','Audio stopped. You can follow the written board steps.'));window.speechSynthesis.speak(u)}
function localView(){prepare(state);return {state,revision,diagnosticQuestion:state.diagnostic.done?null:diagnosticQuestion(state,lang),questions:Object.fromEntries(Object.keys(state.units).map(id=>[id,unitQuestion(state,id,lang)])),support:Object.fromEntries(Object.keys(state.units).map(id=>[id,supportFor(state,id,lang)])),capabilities:{cloud:false,ai:false,email:false,sms:false}}}
async function refresh(){if(local){data=localView();return}const r=await fetch('/api/learning?language='+lang,{credentials:'same-origin',cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.error);data=j;state=prepare(j.state);revision=j.revision}
async function act(action,p={}){if(busy||chatBusy)return false;busy=true;if(['hint','notes'].includes(action))captureDraft();root.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{if(local){const q=action==='answer'?unitQuestion(state,p.topic,lang):null;if(action!=='minutes')feedback=q&&state.units[p.topic]?.mode!=='test'?{correct:correct(q,p.value),hint:correct(q,p.value)?'':q.hint}:null;apply(state,action,p,lang);revision++;try{localStorage.setItem(localKey,JSON.stringify(state))}catch{notice(w('Bu cihazda kayıt tutamıyoruz. Ayrılmadan önce raporunu indir.','This device cannot save. Export your records before leaving.'))}data=localView()}else{const r=await fetch('/api/learning',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...p,revision,language:lang})}),j=await r.json();if(!r.ok)throw new Error(j.error);data=j;state=prepare(j.state);revision=j.revision;if(action!=='minutes')feedback=j.feedback}
 if(action!=='minutes'){render();if(['hint','notes'].includes(action))restoreDraft()}return true;
 }catch(e){notice(e.message==='reload_required'?w('Başka bir sekmede kayıt değişti. Güncel kayıtları yükledim; cevabını yeniden gönderebilirsin.','Another tab changed the record. The latest version is loaded; you can resubmit.'):w('İşlem kaydedilemedi. Tekrar dene.','Could not save. Please retry.'));try{await refresh();if(action!=='minutes')render()}catch{}return false}finally{busy=false;root.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false)}}
function go(p){feedback=null;stopSpeech();location.hash=p;if(page===p)render()}
function button(text,id,secondary=false){return `<button type="button" id="${id}" class="button ${secondary?'secondary':''}">${text}</button>`}
function layout(content){const l=labels();root.innerHTML=`<div class="layout"><aside class="rail"><a class="logo" href="#discover"><span class="logo-face">m</span> MOLİ<i>.</i></a><span class="rail-label">${w('ÖĞRENME ALANIM','MY LEARNING SPACE')}</span><nav>${Object.entries(l).map(([key,label],i)=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><span aria-hidden="true">${['◇','⌘','▦','◴'][i]}</span>${label}</a>`).join('')}</nav><div class="rail-bottom"><strong>${w('Anla. Düşün. Kendi yolunu bul.','Understand. Think. Find your way.')}</strong>${esc(user?.name||w('Misafir öğrenci','Guest learner'))}<span class="status">${w('8. sınıf matematik','Grade 8 mathematics')}</span></div></aside><div class="workspace"><header class="topbar"><span>${w('Matematik','Mathematics')} / <b>${l[page]||l.route}</b></span><div><button class="button small secondary" id="voice" aria-pressed="${voice}">${voice?'♫':'♪'} ${w(voice?'Ses açık':'Sesi aç',voice?'Voice on':'Enable voice')}</button><button class="button small secondary" id="language">${lang.toUpperCase()}</button>${user?`<a href="/?view=account">${w('Hesabım','My account')}</a><button class="button link" id="logout">${w('Çıkış','Sign out')}</button>`:`<a href="/">${w('Giriş yap','Sign in')}</a>`}</div></header>${local?`<div class="save-warning">${user?w('Cihaz içi pilot kaydı · Hesaba senkronizasyon şu anda etkin değil.','Device-only pilot · Cloud sync is not active.'):w('Misafir denemesi · Kayıtların bu tarayıcıda tutulur.','Guest preview · Records stay in this browser.')} <button class="button link" id="retry-cloud">${w('Yeniden bağlan','Reconnect')}</button></div>`:''}<main class="content">${content}<footer>${w('MOLİ · Matematiği anlamak için birlikte düşünüyoruz.','MOLİ · Thinking together to understand mathematics.')}</footer></main></div></div>`;
 $('#language').onclick=async()=>{if(busy||chatBusy)return;stopSpeech();captureDraft();lang=lang==='tr'?'en':'tr';try{localStorage.setItem('moli.language',lang)}catch{}feedback=null;await refresh();render();restoreDraft()};$('#voice').onclick=()=>{if(!('speechSynthesis'in window)){notice(w('Bu tarayıcıda sesli okuma bulunmuyor.','Speech playback is unavailable in this browser.'));return}voice=!voice;$('#voice').setAttribute('aria-pressed',String(voice));$('#voice').textContent=w(voice?'♫ Ses açık':'♪ Sesi aç',voice?'♫ Voice on':'♪ Enable voice');if(voice)speak($('#spoken')?.getAttribute('data-speech')||$('#spoken')?.textContent||w('Merhaba, birlikte düşünmeye hazırım.','Hello, I’m ready to think with you.'));else stopSpeech()};if($('#logout'))$('#logout').onclick=logout;if($('#retry-cloud'))$('#retry-cloud').onclick=()=>location.reload();document.documentElement.lang=lang;
}
function captureDraft(){pendingDraft={answer:$('#answer-value')?.value||'',denominator:$('#answer-denominator')?.value||'',reason:$('#reason')?.value||'',question:$('#coach-input')?.value||''}}
function restoreDraft(){if(!pendingDraft)return;for(const [selector,key]of [['#answer-value','answer'],['#answer-denominator','denominator'],['#reason','reason'],['#coach-input','question']])if($(selector))$(selector).value=pendingDraft[key];pendingDraft=null}
function intro(heading,desc){return `<div class="eyebrow">${w('SENİN HIZINDA, BİRLİKTE','TOGETHER, AT YOUR PACE')}</div><h1>${heading}</h1><p class="lead">${desc}</p>`}
function chart(){return `<div class="legend"><span>● ${w('Başlangıç yanıtları','Starting responses')}</span><span>│ ${w('Çalışma hedefi: %80','Practice target: 80%')}</span></div><div class="bars" role="img" aria-label="${w('Konu bazında başlangıç grafiği, çalışma hedefi yüzde 80','Starting skill chart by topic; practice target 80 percent')}">${baseline(state).map(t=>`<div><div class="bar-label"><span>${esc(t.title[lang])}</span><b>${t.score===null?'—':t.score+'%'}</b></div><div class="bar-track"><div class="bar-fill" style="width:${t.score||0}%"></div><div class="bar-target"></div></div></div>`).join('')}</div><p class="subtle">${w('Her konuda iki soru: başlangıç örneklemi, kesin bir yetenek veya LGS puanı ölçümü değil. %80, konu çalışmalarımız için seçtiğimiz hedeftir.','Two questions per topic: a starting sample, not an ability label or LGS score. 80% is our chosen practice target.')}</p>`}
function moliAvatar(){return '<div class="moli-avatar" aria-hidden="true"><span class="antenna"></span><i></i><i></i><b>⌣</b></div>'}
function neutralCoach(){return `<aside class="moli-panel neutral"><div class="moli-identity">${moliAvatar()}<div><h2>MOLİ</h2><span class="status">${w('Seni tanıyorum','Getting to know you')}</span></div></div><div class="coach-line">${w('Bu bölümde soruları kendi başına çözmeni istiyorum. Bilmediğinde “Henüz bilmiyorum” diyebilirsin. Bitirince sonuçlarına birlikte bakıp derslere başlayacağız.','Work independently in this part. You can say “I don’t know yet.” Afterwards, we will review the results and begin learning together.')}</div><p class="subtle">${w('Çözüm yardımı kapalı · Soruyu sesli dinleyebilirsin.','Solution assistance is off · You can listen to the question.')}</p></aside>`}
function questionForm(q,diagnostic=false){return `<form id="answer-form" data-question="${esc(q.id)}"><span class="reading-goal">${esc(q.readingGoal||'')}</span><div class="question" id="spoken" data-speech="${esc(q.text)}">${rich(q.text)}</div>${q.visual?visual(q.visual,q):''}${q.open?`<div class="answer-entry"><label class="field">${w('Cevabın','Your answer')}<span class="fraction-input ${answerFraction?'is-fraction':''}"><input id="answer-value" required maxlength="100" autocomplete="off" aria-label="${w(answerFraction?'Pay':'Sayısal cevap',answerFraction?'Numerator':'Numeric answer')}"><span class="fraction-divider" ${answerFraction?'':'hidden'}></span><input id="answer-denominator" ${answerFraction?'':'hidden'} ${answerFraction?'required':''} maxlength="100" aria-label="${w('Payda','Denominator')}"></span></label>${button(w(answerFraction?'Sayı olarak yanıtla':'Kesirle yanıtla',answerFraction?'Use a number':'Use a fraction'),'fraction-toggle',true)}<span id="answer-preview" aria-live="polite"></span></div><label class="field">${w('Nasıl düşündüğünü anlat (isteğe bağlı)','Explain your reasoning (optional)')}<textarea id="reason" maxlength="1500" placeholder="${w('Hangi bilgileri kullandın? Neden bu işlemi seçtin?','What did you use? Why did you choose this operation?')}"></textarea></label>`:`<fieldset class="question-choices"><legend class="subtle">${w('Bir cevap seç','Choose one answer')}</legend><div class="choices">${q.choices.map((n,i)=>`<label class="choice"><input type="radio" name="choice" value="${n}" required><span><b>${String.fromCharCode(65+i)}</b> ${math(fraction(n))}</span></label>`).join('')}</div></fieldset>`}<div class="actions"><button class="button" type="submit">${w(diagnostic?'Yanıtla ve ilerle →':'Yanıtımı gönder →',diagnostic?'Answer and continue →':'Submit my answer →')}</button>${button(w('Soruyu dinle','Listen to question'),'listen',true)}</div><p class="subtle">${w('Sayısal sonuç kontrol edilir; açıklaman öğrenme kaydına eklenir. Açıklamanın rubrik değerlendirmesi henüz etkin değil.','The numeric result is checked and your reasoning is saved. Rubric evaluation of explanations is not active yet.')}</p></form>`}
function bindQuestion(q,diagnostic=false){$('#answer-form').onsubmit=async e=>{e.preventDefault();let value=q.open?$('#answer-value').value:$('input[name=choice]:checked')?.value;if(q.open&&answerFraction){const d=$('#answer-denominator').value;if(!d.trim()||Number(d.replace(',','.'))===0)return notice(w('Payda sıfır olamaz.','The denominator cannot be zero.'));value=value+'/'+d}if(!value?.trim())return;stopSpeech();boardMode='lesson';revealed=0;const wasTest=selected&&state.units[selected]?.mode==='test';if(await act(diagnostic?'diagnostic':'answer',{topic:q.topic,id:q.id,value,reason:$('#reason')?.value||''})){if(!diagnostic&&!wasTest&&feedback)speak(feedback.correct?w('İlişkiyi doğru kurdun. Sonucunun ne anlama geldiğini de düşünelim.','You modelled the relationship correctly. Think about what the result means.'):feedback.hint);if(diagnostic&&state.diagnostic.done)speak(w('Başlangıç haritan hazır. Şimdi sana uygun yoldan birlikte ilerleyebiliriz.','Your starting map is ready. Now we can follow a path that fits you.'))}};
 $('#listen').onclick=()=>{voice=true;speak(q.text)};if($('#fraction-toggle')){$('#fraction-toggle').onclick=()=>{captureDraft();answerFraction=!answerFraction;render();restoreDraft();$('#answer-denominator').hidden=!answerFraction;$('#answer-denominator').required=answerFraction};const preview=()=>{let tex=$('#answer-value').value;if(answerFraction)tex=`\\frac{${tex.replace(/[^0-9.,+-]/g,'')}}{${$('#answer-denominator').value.replace(/[^0-9.,+-]/g,'')}}`;else tex=tex.replace(/[^0-9.,+-]/g,'');$('#answer-preview').innerHTML=tex?math(tex):''};$('#answer-value').oninput=preview;$('#answer-denominator').oninput=preview}}
function discover(){if(!state.diagnostic.started){layout(intro(w('Önce nereden başlayacağını bulalım.','Let’s find your starting point.'),w('Durumları yorumladığın, ilişkiler kurduğun 26 kısa soruyla seni tanıyacağım. Sonra birlikte öğrenme rotanı ve çalışma planını oluşturacağız.','I will get to know you through 26 short questions about interpreting situations and connecting ideas. Then we will build your learning path and study plan.'))+`<div class="classroom-grid"><section class="card hero"><span class="pill">${w('26 soru · Kendi hızında','26 questions · At your own pace')}</span><h2>${w('Bu bir yarış değil.','This is not a race.')}</h2><p id="spoken">${w('Bazı sorular seçenekli, bazılarında cevabını sen yazacaksın. Soruları yardım almadan çözmen, sana daha uygun bir başlangıç seçmemizi sağlayacak. Bilmediğinde geçebilirsin.','Some questions have choices; others ask for your own answer. Solving independently helps us choose a better starting point. You can skip questions you do not know.')}</p>${button(w('Seviyemi keşfedelim →','Discover my starting point →'),'start')}</section>${neutralCoach()}</div>`);$('#start').onclick=()=>act('start');return}
 if(state.diagnostic.done){layout(intro(w('Başlangıç haritan hazır.','Your starting map is ready.'),w('Sonuçlar bir etiket değil, birlikte hangi konulara odaklanacağımızın işareti.','These results are not a label; they help us choose what to work on together.'))+`<div class="grid"><section class="card"><h2>${w('Bugünkü başlangıç noktan','Your starting point today')}</h2>${chart()}</section><section><div class="card hero">${moliAvatar()}<p id="spoken">${w('Her konuda iki soruya baktık. Bazı fikirler sağlam, bazılarını beraber güçlendireceğiz. Önce bir durumu anlamaya, sonra neden o işlemi yaptığımızı açıklamaya çalışacağız.','We sampled two questions per topic. Some ideas are already strong; others we will build together. We will understand situations first, then explain why our methods work.')}</p>${button(w('Öğrenme rotama geç →','Open my learning path →'),'to-route')}<div class="actions">${button(w('Programımı oluşturalım','Build my study plan'),'to-plan',true)}</div></div><div class="card"><h3>${w('Derslerimiz nasıl ilerleyecek?','How will lessons work?')}</h3><ol class="journey"><li>${w('MOLİ tahtada anlatır, sen her adımda soru sorabilirsin.','MOLİ explains on the board; ask questions at any step.')}</li><li>${w('Bir soruyu önce sen denersin, gerekirse birlikte çözeriz.','Try a problem first, then work together when needed.')}</li><li>${w('Sonunda bağımsız testle ne öğrendiğine bakarız.','An independent test checks what you learned.')}</li></ol></div></section></div>`);$('#to-route').onclick=()=>go('route');$('#to-plan').onclick=()=>go('plan');return}
 const q=data.diagnosticQuestion;layout(intro(w('Bir soruyla başlayalım.','One question at a time.'),w('Soruyu anla, gerekli bilgiyi seç ve kendi yolunu dene.','Understand the situation, choose the useful information and try your own approach.'))+`<div class="classroom-grid"><section class="card question-card"><div class="panel-topline"><span class="pill">${state.diagnostic.answers.length+1} / 26</span><span class="pill">${esc(title(q.topic))}</span></div><div class="progress"><span style="width:${state.diagnostic.answers.length/26*100}%"></span></div>${questionForm(q,true)}<div class="actions">${button(w('Henüz bilmiyorum, geç','I don’t know yet — skip'),'skip',true)}</div></section>${neutralCoach()}</div>`);bindQuestion(q,true);$('#skip').onclick=()=>act('diagnostic',{id:q.id,value:'skip'});
}
function gate(){layout(intro(w('Önce başlangıç noktanı bulalım.','Let’s find your starting point first.'),w('Kişisel rota ve program için Keşif atölyesini tamamla.','Complete the discovery assessment to unlock your personal path and plan.'))+`<div class="card">${button(w('Keşif atölyesine git →','Open the discovery studio →'),'gate')}</div>`);$('#gate').onclick=()=>go('discover')}
function route(){if(!state.diagnostic.done)return gate();if(selected&&state.units[selected])return lesson();const next=state.order.find(id=>!state.units[id]?.passed);layout(intro(w('Sınıfın hazır. Birlikte başlayalım.','Your classroom is ready. Let’s begin.'),w('Anlatımı dinle, tahtayı takip et, sorunu sor. Önce birlikte, sonra kendi başına çöz.','Listen, follow the board and ask questions. Solve together first, then independently.'))+`<section class="card hero"><span class="pill">${w('Sıradaki konu','Up next')}</span><h2>${next?esc(title(next)):w('Başlangıç rotanı tamamladın!','You completed your initial path!')}</h2><p>${w('Tahtada anlatım → Birlikte çözüm → Bağımsız test → Bir sonraki konu.','Board explanation → Guided solving → Independent test → Next topic.')}</p>${next?button(w('Derse gir →','Enter classroom →'),'continue'):''}</section><section class="card"><h2>${w('Kişisel öğrenme rotan','Your learning path')}</h2>${state.order.map((id,i)=>{const u=state.units[id],canOpen=unlocked(state,id);return `<div class="topic ${canOpen?'':'locked'}"><span class="topic-number">${u?.passed?'✓':i+1}</span><div><strong>${esc(title(id))}</strong><span class="subtle">${u?.passed?w('Tamamlandı','Completed'):canOpen?w('Öğrenmeye hazır','Ready to learn'):w('Önceki konuyu tamamladığında açılır','Opens after the previous topic')}${u?.attempts.length?' · '+w('Son test: ','Latest test: ')+u.attempts.at(-1).score+'%':''}</span></div>${canOpen?`<button class="button small secondary" data-open="${id}">${w('Sınıfa gir →','Enter →')}</button>`:'<span aria-hidden="true">⌑</span>'}</div>`}).join('')}</section>`);root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openUnit(b.dataset.open));if($('#continue'))$('#continue').onclick=()=>openUnit(next)}
async function openUnit(id){stopSpeech();if(await act('open',{topic:id})){selected=id;feedback=null;boardMode='lesson';revealed=0;coachError='';render()}}
function boardLines(lines){return lines.map((line,i)=>`<div class="board-line ${i<revealed?'written':''}" id="board-line-${i}" data-board-index="${i}"><span class="chalk-index">${i+1}</span><div>${line.math?`<div class="board-math">${math(line.math,true)}</div>`:''}${line.text?`<p>${rich(line.text)}</p>`:''}${line.note||line.explanation?`<p class="board-note">${rich(line.note||line.explanation)}</p>`:''}</div></div>`).join('')}
function whiteboard(id,u){const slides=lessonSlides(id,lang),slide=slides[u.slide||0],reply=u.boardReplies?.at(-1),ai=boardMode==='ai'&&reply,lines=ai?reply.steps:slide.lines;return `<section class="whiteboard-wrap"><div class="whiteboard-toolbar"><div><span class="board-dot"></span> ${w('Ders tahtası','Classroom board')}</div><div>${button(w('Ders','Lesson'),'lesson-board',boardMode==='ai')}${reply?button(w('MOLİ’nin yanıtı','MOLİ’s answer'),'ai-board',boardMode!=='ai'):''}</div></div><div class="whiteboard" id="whiteboard"><div class="board-heading"><span class="eyebrow">${esc(title(id))}</span><h2>${esc(ai?reply.title:slide.title)}</h2></div><div class="board-lines" id="board-lines">${boardLines(lines)}</div>${!ai&&slide.visual?visual(slide.visual,null,id==='slope'):''}<div class="board-prompt">${rich(ai?reply.question:slide.prompt)}</div></div><div class="board-controls">${button(w('♫ Tahtada anlat','♫ Explain on the board'),'play-slide')}${button(w('Bir sonraki satır','Next board line'),'write-line',true)}${button(w('■ Durdur','■ Stop'),'stop-reading',true)}<span class="subtle">${w('Satırlar anlatımla birlikte belirginleşir.','Lines highlight as MOLİ explains.')}</span></div></section>`}
function lesson(){const id=selected,u=state.units[id],mode=u.mode,q=data.questions[id];const isTest=mode==='test',isLesson=mode==='lesson',supported=['guided','practice'].includes(mode);const heading=isLesson?w('Önce anlayalım.','Let’s understand first.'):mode==='guided'?w('Önce sen dene. Birlikte düşünelim.','Try first. Let’s think together.'):mode==='test'?w('Şimdi sıra sende.','Now it is your turn.'):mode==='practice'?w('Bir adım geri, daha sağlam ilerleyelim.','Build a stronger next step.'):mode==='ready'?w('Birlikte denedik. Şimdi kendi başına.','We practised together. Now try independently.'):w('Bu konuyu tamamladın.','You completed this topic.');
 const support=data.support?.[id];let body;
 if(isLesson)body=whiteboard(id,u)+`<section class="card teaching-summary"><h3 id="spoken" data-speech="${esc(lessonSlides(id,lang)[u.slide||0].speech)}">${w('MOLİ anlatıyor','MOLİ explains')}</h3><p class="lesson-text">${rich(lessonSlides(id,lang)[u.slide||0].speech)}</p><div class="lesson-pager"><span>${w('Bölüm','Section')} ${(u.slide||0)+1} / ${SLIDE_COUNT}</span>${button(w((u.slide||0)===SLIDE_COUNT-1?'Birlikte soru çözelim →':'Anladım, devam edelim →',(u.slide||0)===SLIDE_COUNT-1?'Solve together →':'I understand, continue →'),'next-slide')}</div></section>`;
 else if(mode==='done')body=`<section class="card hero"><span class="face">✓</span><h2>${w('Bir adım daha ilerledin.','Another step forward.')}</h2><p id="spoken">${w('Bağımsız testte hedefe ulaştın. Sıradaki konu açıldı. İstersen bu konuyu tahtada tekrar dinleyebilir veya farklı sorularla ek pratik yapabilirsin.','You met the target independently. The next topic is open. You can revisit the board explanation or take an extra practice test.')}</p><span class="pill">${u.attempts.at(-1)?.score}%</span><div class="actions">${button(w('Rotama dön →','Back to my path →'),'back-path')}${button(w('Ek test','Extra test'),'extra',true)}${button(w('Tahtada tekrar anlat','Explain again'),'review',true)}</div></section>`;
 else if(mode==='ready')body=`<section class="card hero"><h2>${w('Kendi çözüm yolunu denemeye hazır mısın?','Ready to try your own approach?')}</h2><p id="spoken">${w('İki soruda birlikte çalıştık. Şimdi 5 soruluk bağımsız testle düşüncelerini kendi başına uygulayacaksın. Bu bölümde çözüm yardımı kapalı olacak; bitince yanlışlarının üzerinden birlikte geçeceğiz.','We worked through two problems together. Now apply your ideas in a five-question independent test. Solution help will be off; afterwards we can review any difficulties together.')}</p>${button(w('Bağımsız teste başla →','Begin independent test →'),'begin-test')}</section>`;
 else body=`<section class="card question-card"><div class="panel-topline"><span class="pill">${isTest?w(`Bağımsız test · ${u.testAnswers.length+1}/5`,`Independent test · ${u.testAnswers.length+1}/5`):w(mode==='guided'?`Birlikte çözüm · ${(u.guidedCount||0)+1}/2`:`Destek çalışması · ${u.practiceCorrect}/2`,mode==='guided'?`Guided solving · ${(u.guidedCount||0)+1}/2`:`Support practice · ${u.practiceCorrect}/2`)}</span><span class="pill gold">${isTest?w('MOLİ çözüm yardımı kapalı','MOLİ solution assistance off'):w('Önce sen dene','Try first')}</span></div>${feedback&&!isTest?`<div class="feedback ${feedback.correct?'':'retry'}" role="status">${rich(feedback.correct?w('Doğru ilişki! Şimdi başka bir duruma taşıyalım.','Correct relationship! Let’s try a different situation.'):w('Birlikte tekrar düşünelim. ','Let’s think again. ')+feedback.hint)}</div>`:''}${questionForm(q)}${supported&&u.lastWrong?`<section class="guided-board"><div class="moli-head"><h3>${w('MOLİ tahtada yardımcı oluyor','MOLİ helps on the board')}</h3><span class="pill">${u.hintLevel}/3</span></div>${boardLines((support?.steps||[]))}<div class="actions">${u.hintLevel<3?button(w('Bir adım daha göster','Show one more step'),'hint',true):`<p>${w('Şimdi bu adımları kullanıp cevabını yeniden dene.','Use these steps to try your answer again.')}</p>`}${button(w('Adımı sesli açıkla','Explain this step aloud'),'read-hint',true)}</div></section>`:''}${mode==='practice'&&u.practiceCorrect>=2?`<div class="actions">${button(w('Yeni bağımsız teste hazırım →','Ready for a new independent test →'),'retest')}</div>`:''}</section>${isTest?'':boardMode==='ai'&&u.boardReplies?.length?whiteboard(id,u):''}`;
 layout(intro(esc(title(id)),heading)+`<div class="classroom-top"><div class="phase-strip">${[w('Tahtada anlatım','Board lesson'),w('Birlikte çözüm','Guided solving'),w('Bağımsız test','Independent test')].map((s,i)=>`<span class="${i===(isLesson?0:isTest?2:1)?'current':''}">${i+1} · ${s}</span>`).join('')}</div>${button(w('← Konu listesi','← Topic list'),'list',true)}</div><div class="classroom-grid"><div class="teaching-column">${body}${notes(id,u)}</div>${coach(id,isTest)}</div>`);
 $('#list').onclick=()=>{stopSpeech();selected='';feedback=null;render()};if(q)bindQuestion(q);for(const [b,a]of [['next-slide','next-slide'],['begin-test','begin-test'],['hint','hint'],['retest','retest'],['extra','extra'],['review','review']])if($('#'+b))$('#'+b).onclick=async()=>{stopSpeech();boardMode='lesson';revealed=0;if(await act(a,{topic:id})){if(a==='hint')speak(data.support[id]?.steps.at(-1)?.note||'');else if(a==='next-slide'&&state.units[id].mode==='lesson')speak(lessonSlides(id,lang)[state.units[id].slide].speech)}};
 if($('#back-path'))$('#back-path').onclick=()=>{selected='';render()};if($('#read-hint'))$('#read-hint').onclick=()=>{voice=true;speak((support?.steps||[]).map(x=>x.note).join(' '))};bindBoard(id,u);bindCoach(id,isTest);bindNotes(id);
}
function notes(id,u){return `<details class="card board-notes"><summary>${w('Kendi düşünme alanım','My thinking space')}</summary><label class="field">${w('Bir ilişki, tahmin veya çözüm adımı not et.','Note a relationship, prediction or solution step.')}<textarea id="board-notes" maxlength="3000">${esc(u.notes||'')}</textarea></label>${button(w('Notumu kaydet','Save my note'),'save-notes',true)}</details>`}
function bindNotes(id){if($('#save-notes'))$('#save-notes').onclick=async()=>{if(await act('notes',{topic:id,text:$('#board-notes').value}))notice(w('Notun öğrenme kaydına eklendi.','Your note was saved with your learning records.'))}}
function bindBoard(id,u){if(!$('#whiteboard'))return;const getContent=()=>boardMode==='ai'&&u.boardReplies?.length?{speech:u.boardReplies.at(-1).speech,lines:u.boardReplies.at(-1).steps}:{speech:lessonSlides(id,lang)[u.slide||0].speech,lines:lessonSlides(id,lang)[u.slide||0].lines};
 $('#lesson-board').onclick=()=>{stopSpeech();boardMode='lesson';revealed=0;render()};if($('#ai-board'))$('#ai-board').onclick=()=>{stopSpeech();boardMode='ai';revealed=0;render()};$('#stop-reading').onclick=stopSpeech;$('#write-line').onclick=()=>{const c=getContent();revealed=Math.min(c.lines.length,revealed+1);root.querySelectorAll('[data-board-index]').forEach((el,i)=>el.classList.toggle('written',i<revealed))};$('#play-slide').onclick=()=>{if(!('speechSynthesis'in window))return notice(w('Sesli okuma desteklenmiyor. Satırları düğmeyle takip edebilirsin.','Speech playback is unavailable. Use the line button instead.'));stopSpeech();voice=true;const token=readingToken,c=getContent();revealed=0;root.querySelectorAll('[data-board-index]').forEach(el=>el.classList.remove('written'));const next=i=>{if(token!==readingToken)return;if(i>=c.lines.length)return;revealed=i+1;$('#board-line-'+i)?.classList.add('written');const line=c.lines[i];speak(line.note||line.explanation||line.text||line.math,()=>next(i+1))};speak(c.speech,()=>next(0))};
 root.querySelectorAll('[data-ramp]').forEach(input=>input.oninput=()=>{const rise=+$('#ramp-rise').value,run=+$('#ramp-run').value;$('#ramp-drawing').innerHTML=rampSvg(rise,run);$('#ramp-rise-value').textContent=fmt(rise)+' m';$('#ramp-run-value').textContent=fmt(run)+' m'});
}
function coach(id,independent=false){const u=state.units[id],msgs=state.messages.filter(m=>m.context===id&&m.role==='user'||m.context===id&&m.role==='assistant').slice(-8);return `<aside class="moli-panel"><div class="moli-identity">${moliAvatar()}<div><h2>MOLİ</h2><span class="status">${w(independent?'Bağımsız çalışma':'Matematik öğretmenin',independent?'Independent work':'Your mathematics teacher')}</span></div></div><div class="coach-line">${independent?w('Bu sorularda kendi düşünme yolunu görmek istiyorum. Bitirdiğinde zorlandığın adımları beraber ele alacağız.','I want to see your own thinking on these problems. Afterwards, we will work through the difficult steps together.'):w(u.mode==='lesson'?'Tahtada birlikte ilerliyoruz. Takıldığın satırı sorabilir veya başka bir örnek isteyebilirsin.':'Önce sen dene. Yanlış cevabın da düşünceni anlamama yardımcı olur; sonra küçük adımlarla birlikte ilerleriz.',u.mode==='lesson'?'Follow the board with me. Ask about a step or request another example.':'Try first. An incorrect answer also helps me understand your thinking; then we can work in small steps together.')}</div>${independent?`<div class="independent-note">${w('Çözüm desteği test bitene kadar kapalı.','Solution support is paused until the test ends.')}</div>`:`<div class="conversation" id="conversation" role="log" aria-live="polite">${msgs.map(m=>`<div class="bubble ${m.role==='user'?'user':''}"><b>${m.role==='user'?w('Sen','You'):'MOLİ'}</b><div>${rich(m.text)}</div></div>`).join('')}</div><div class="coach-error" id="coach-error" role="status">${esc(coachError)}</div><form id="coach-form"><label class="field">${w('MOLİ’ye sor','Ask MOLİ')}<textarea id="coach-input" required maxlength="1200" placeholder="${w('Bu adım neden böyle? Başka bir örnekle açıklar mısın?','Why does this step work? Could you show another example?')}"></textarea></label><div class="coach-actions"><button class="button" type="submit">${w('Sorumu yanıtla','Answer my question')}</button>${button(w('♩ Konuş','♩ Speak'),'coach-mic',true)}</div></form><p class="subtle">${data.capabilities.ai?w('Yanıt, bulunduğun ders ve soru adımıyla birlikte hazırlanır. Ses açıksa MOLİ konuşur.','Replies use your current lesson and question context. Enable voice to hear MOLİ.'):w('Canlı AI bağlantısı henüz açık değil. Ders tahtası ve hazırlanmış çözüm adımları kullanılabilir.','Live AI is not connected yet. The lesson board and authored solution steps remain available.')}</p>`}</aside>`}
function errorText(code){return ({ai_not_configured:w('Canlı MOLİ bağlantısı henüz etkin değil. Bağlantı kurulmadan sana hazır bir paragrafı AI yanıtı gibi tekrarlamayacağım.','Live MOLİ is not connected yet. Prepared paragraphs will not be presented as AI replies.'),ai_credits_required:w('MOLİ bağlantısı için AI hesabında kullanım kredisi gerekiyor.','The AI account needs available credits.'),ai_activation_required:w('AI hizmetinde hesap etkinleştirmesi gerekiyor.','The AI service requires account activation.'),ai_auth_required:w('AI bağlantısının yetkilendirmesi tamamlanmalı.','AI connection authentication needs setup.'),rate_limited:w('Kısa bir süre bekleyip tekrar sorabilirsin.','Please wait briefly before asking again.'),reload_required:w('Ders kaydı başka bir sekmede değişti. Sorunu yeniden gönderebilirsin.','The lesson changed in another tab. You can resend your question.')})[code]||w('MOLİ şu an yanıt veremedi. Sorun burada kaldı; tekrar deneyebilirsin.','MOLİ could not reply. Your question is preserved so you can retry.')}
function bindCoach(id,independent){if(independent||!$('#coach-form'))return;$('#coach-form').onsubmit=async e=>{e.preventDefault();if(chatBusy||busy)return;const text=$('#coach-input').value.trim();if(!text)return;captureDraft();coachError='';if(local){coachError=errorText('ai_not_configured');$('#coach-error').textContent=coachError;return}chatBusy=true;$('#coach-form button').disabled=true;$('#coach-form button').textContent=w('MOLİ düşünüyor…','MOLİ is thinking…');const requestPhase=state.units[id].mode;try{const r=await fetch('/api/tutor',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:id,text,language:lang})}),j=await r.json();if(!r.ok)throw new Error(j.error);await refresh();if(page==='route'&&selected===id&&state.units[id].mode===requestPhase){boardMode='ai';revealed=0;render();restoreDraft();$('#coach-input').value='';speak(j.reply.speech+' '+j.reply.question);$('#conversation').scrollTop=$('#conversation').scrollHeight}}catch(e){coachError=errorText(e.message);try{await refresh()}catch{}if(page==='route'&&selected===id){render();restoreDraft()}}finally{chatBusy=false;if($('#coach-form button')){$('#coach-form button').disabled=false;$('#coach-form button').textContent=w('Sorumu yanıtla','Answer my question')}}};$('#coach-mic').onclick=()=>{const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API)return notice(w('Bu tarayıcı mikrofonla yazmayı desteklemiyor. Sorunu yazarak sorabilirsin.','Speech input is unavailable in this browser. Type your question instead.'));mic?.abort();stopSpeech();mic=new API();mic.lang=lang==='tr'?'tr-TR':'en-US';mic.onresult=e=>{if($('#coach-input'))$('#coach-input').value=e.results[0][0].transcript;notice(w('Sorun yazıya çevrildi. Kontrol edip gönder.','Your question is transcribed. Check it before sending.'))};mic.onerror=e=>{if(e.error!=='aborted')notice(w('Mikrofon iznini kontrol et.','Check microphone permission.'))};notice(w('Konuşmayı tarayıcın yazıya çevirir; ses sağlayıcıya gönderilebilir. Ses dosyası saklamıyoruz.','Your browser transcribes speech and may send audio to its provider. We do not store audio files.'));mic.start()}}
function rampSvg(rise,run){const x=55,y=160,scale=Math.min(300/run,130/rise),end=x+run*scale,top=y-rise*scale;return `<svg width="460" height="210" viewBox="0 0 460 210" role="img" aria-label="${w('Rampanın yüksekliği','Ramp rise')} ${rise} m, ${w('yatay mesafe','horizontal run')} ${run} m"><path d="M${x} ${y}L${end} ${top}L${end} ${y}Z" fill="#dbe8cd" stroke="#6d925f" stroke-width="4"/><path d="M${x} 178H${end}M${end+25} ${top}V${y}" stroke="#b89c62" stroke-width="2" stroke-dasharray="5"/><text x="${(x+end)/2}" y="201" fill="#315449">${fmt(run)} m</text><text x="${end+35}" y="${(top+y)/2}" fill="#315449">${fmt(rise)} m</text></svg>`}
function visual(kind,q=null,interactive=false){const a=q?2+q.seed%5:2,b=q?3+(q.seed*3)%5:4;let svg='';const text=(x,y,s)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#365446" font-size="16">${esc(s)}</text>`;
 if(kind==='ramp')return `<div class="scene-diagram"><div id="ramp-drawing">${rampSvg(a,q?b*2:8)}</div>${interactive?`<div class="ramp-inputs"><label>${w('Yükseklik','Rise')} <output id="ramp-rise-value">2 m</output><input id="ramp-rise" data-ramp type="range" min="1" max="4" step=".5" value="2"></label><label>${w('Yatay mesafe','Horizontal run')} <output id="ramp-run-value">8 m</output><input id="ramp-run" data-ramp type="range" min="4" max="12" step="1" value="8"></label></div>`:''}</div>`;
 if(kind==='square'||kind==='squares'){svg=`<rect x="60" y="25" width="130" height="130" fill="#dce8cf" stroke="#78966b" stroke-width="2"/>${text(125,95,kind==='square'?`${q?a*a:50} m²`:'3 × 3')}`;if(kind==='squares')svg+=`<rect x="240" y="15" width="160" height="160" fill="#eae0c8" stroke="#b99b5f"/><path d="M320 15V175M240 95H400" stroke="#b99b5f"/>${text(320,194,'6 × 6')}`}
 else if(kind==='triangle')svg=`<path d="M70 155L235 25L390 155Z" fill="#e1ead7" stroke="#78966b" stroke-width="3"/>${text(105,145,(q?a*10:50)+'°')}${text(350,145,(q?b*10:60)+'°')}${text(235,62,'?')}`;
 else if(kind==='marbles')svg=Array.from({length:a+b},(_,i)=>`<circle cx="${60+(i%8)*45}" cy="${70+Math.floor(i/8)*55}" r="15" fill="${i<a?'#b8796b':'#7f9fae'}"/>`).join('');
 else if(kind==='bars'){const values=q?[a,a+b,a+2*b]:[12,18,24];svg=values.map((n,i)=>`<rect x="${75+i*100}" y="${160-n*4}" width="55" height="${n*4}" fill="#9bb38b"/>${text(103+i*100,150-n*4,n)}${text(103+i*100,185,w('Gün ','Day ')+(i+1))}`).join('')}
 else if(kind==='coordinates')svg=`<path d="M40 100H420M230 10V185" stroke="#a3b39a" stroke-width="2"/><path d="M230 10V185" stroke="#b89c62" stroke-width="3" stroke-dasharray="5"/><circle cx="310" cy="45" r="7" fill="#38614f"/>${text(350,40,`(${q?a:2}, ${q?b:3})`)}${text(240,195,'0')}${text(245,20,'y')}`;
 else if(kind==='cylinder')svg=`<path d="M155 55V150C155 185 315 185 315 150V55" fill="#dfead9" stroke="#78966b" stroke-width="2"/><ellipse cx="235" cy="55" rx="80" ry="30" fill="#edf3e6" stroke="#78966b" stroke-width="2"/><path d="M235 55H315" stroke="#b89c62" stroke-width="2"/>${text(275,47,`r = ${a} cm`)}${text(370,115,`h = ${q?b:5} cm`)}`;
 else if(kind==='numberline')svg=`<path d="M50 105H420" stroke="#78966b" stroke-width="3"/><path d="M65 105H290" stroke="#b89c62" stroke-width="6"/><circle cx="290" cy="105" r="8" fill="#fff" stroke="#b89c62" stroke-width="3"/>${text(290,140,'k')}${text(100,75,'x < k')}`;
 else if(kind==='balance')svg=`<path d="M235 65V160M155 165H315M90 65H380" stroke="#8ba17d" stroke-width="5"/><path d="M110 65L80 125H175L150 65M315 65L285 125H380L355 65" stroke="#8ba17d" stroke-width="2" fill="#e6eddc"/>${text(128,113,'x + …')}${text(332,113,w('toplam','total'))}`;
 else if(kind==='groups')svg=[q?a*2:24,q?b*2:36].map((n,row)=>Array.from({length:Math.min(n,36)},(_,i)=>`<rect x="${40+(i%18)*21}" y="${35+row*75+Math.floor(i/18)*20}" width="12" height="12" rx="2" fill="${row?'#bca36c':'#8fa97e'}"/>`).join('')).join('');
 else if(kind==='growth')svg=Array.from({length:3},(_,i)=>`<rect x="${45+i*140}" y="55" width="90" height="70" rx="10" fill="#e4ecd9"/>${text(90+i*140,96,i===0?'1':w('× '+(q?a:2),'× '+(q?a:2)))}`).join('');
 return `<div class="scene-diagram"><svg width="460" height="205" viewBox="0 0 460 205" role="img" aria-label="${w('Soru durumunun görsel modeli','Visual model of the situation')}">${svg}</svg></div>`;
}
function plan(){if(!state.diagnostic.done)return gate();const needsSupport=baseline(state).reduce((sum,t)=>sum+(t.score||0),0)/topics.length<50;const p=state.plan||{days:needsSupport?[1,2,4,6]:[1,3,5],time:'18:00',zone:'Europe/Istanbul',minutes:needsSupport?20:30,email:false,sms:false};const names=lang==='tr'?['Paz','Pzt','Sal','Çar','Per','Cum','Cmt']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];layout(intro(w('Birlikte düzen kuralım.','Let’s build a rhythm together.'),w(needsSupport?'Başlangıç haritana göre haftada dört kısa, 20 dakikalık çalışma öneriyorum. Sana uyan gün ve saatleri birlikte seçelim.':'Başlangıç haritana göre haftada üç, 30 dakikalık çalışma öneriyorum. Sana uyan gün ve saatleri birlikte seçelim.',needsSupport?'Your starting map suggests four short, 20-minute sessions per week. Let’s choose days and times that suit you.':'Your starting map suggests three 30-minute sessions per week. Let’s choose days and times that suit you.'))+`<div class="grid equal"><section class="card"><h2>${w('Haftalık çalışma düzenim','My weekly routine')}</h2><form id="plan-form"><label class="field">${w('Günler','Days')}</label><div class="day-picks">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="day" value="${d}" ${p.days.includes(d)?'checked':''}> ${names[d]}</label>`).join('')}</div><div class="grid equal"><label class="field">${w('Başlangıç saati','Start time')}<input type="time" id="plan-time" value="${p.time}" required></label><label class="field">${w('Süre','Duration')}<select id="plan-minutes">${[20,30,45].map(n=>`<option ${p.minutes===n?'selected':''} value="${n}">${n} ${w('dakika','minutes')}</option>`).join('')}</select></label></div><label class="field">${w('Saat dilimi','Time zone')}<select id="plan-zone">${['Europe/Istanbul','America/New_York','Europe/London','UTC'].map(z=>`<option ${p.zone===z?'selected':''}>${z}</option>`).join('')}</select></label><h3>${w('10 dakika önce hatırlat','Remind me 10 minutes before')}</h3><label class="check"><input id="email-reminder" type="checkbox" ${p.email?'checked':''} ${!data.capabilities.email?'disabled':''}>${w('Doğrulanmış hesap e-postama hatırlatma gönder.','Send reminders to my verified account email.')}</label>${!data.capabilities.email?`<p class="subtle">${w('E-posta hatırlatma servisi henüz etkinleştirilmedi.','Email reminder delivery is not activated yet.')}</p>`:''}<label class="check"><input id="sms-reminder" type="checkbox" ${p.sms?'checked':''} ${!data.capabilities.phoneVerified||!data.capabilities.sms?'disabled':''}>${w('Doğruladığım telefonuma SMS gönder.','Send SMS to my verified phone.')}</label>${data.capabilities.sms?phoneForm():`<p class="subtle">${w('SMS için telefon doğrulama ve gönderim servisi henüz etkin değil.','Phone verification and SMS delivery are not activated yet.')}</p>`}<button class="button" type="submit">${w('Planımı kaydet','Save my plan')}</button></form><div class="actions">${button(w('Takvimime indir (.ics)','Download calendar (.ics)'),'calendar',true)}</div></section><section class="card"><h2>${w('Yaklaşan çalışmalarım','My upcoming sessions')}</h2>${state.plan?nextSessions(state.plan).map(iso=>`<div class="session"><strong>${date(iso)}</strong><p class="subtle">${state.plan.minutes} ${w('dakika','minutes')} · ${esc(title(state.order.find(id=>!state.units[id]?.passed)||state.order[0]))}</p></div>`).join(''):`<p class="empty">${w('Planını kaydettiğinde çalışma saatlerin burada görünecek.','Save your plan to see upcoming sessions here.')}</p>`}<p class="subtle">${w('Takvim dosyası 10 dakika öncesine alarm ekler. Alarmın gösterimi takvim uygulamanın ayarlarına bağlıdır.','The calendar file includes a 10-minute reminder. Delivery depends on your calendar app settings.')}</p></section></div>`);
 $('#plan-form').onsubmit=async e=>{e.preventDefault();const days=[...root.querySelectorAll('input[name=day]:checked')].map(x=>+x.value);if(!days.length){notice(w('En az bir gün seç.','Choose at least one day.'));return}if(await act('plan',{days,time:$('#plan-time').value,minutes:+$('#plan-minutes').value,zone:$('#plan-zone').value,email:$('#email-reminder').checked,sms:$('#sms-reminder').checked}))notice(w('Çalışma planın kaydedildi.','Your study plan is saved.'))};$('#calendar').onclick=()=>{if(!state.plan)return notice(w('Önce planını kaydet.','Save your plan first.'));const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const entries=nextSessions(state.plan,new Date(),20).map(iso=>`BEGIN:VEVENT\r\nUID:${user?.id||'demo'}-${stamp(iso)}@moli\r\nDTSTAMP:${stamp(new Date())}\r\nDTSTART:${stamp(iso)}\r\nDTEND:${stamp(new Date(+new Date(iso)+state.plan.minutes*60000))}\r\nSUMMARY:MOLI mathematics\r\nBEGIN:VALARM\r\nTRIGGER:-PT10M\r\nACTION:DISPLAY\r\nDESCRIPTION:MOLI study session\r\nEND:VALARM\r\nEND:VEVENT`);download('moli-plan.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//MOLI//Study//TR\r\n'+entries.join('\r\n')+'\r\nEND:VCALENDAR\r\n','text/calendar')};bindPhone();
}
function phoneForm(){return `<details><summary>${w('SMS telefon doğrulaması','Verify phone for SMS')}${data.capabilities.phoneVerified?' ✓':''}</summary><label class="field">${w('Uluslararası telefon (+90…)','International phone (+90…)')}<input id="phone" type="tel" value="${esc(data.capabilities.phone||'')}" placeholder="+905XXXXXXXXX"></label>${button(w('Kod gönder','Send code'),'phone-send',true)}<label class="field">${w('Doğrulama kodu','Verification code')}<input id="phone-code" inputmode="numeric" maxlength="8"></label>${button(w('Telefonumu doğrula','Verify my phone'),'phone-check',true)}</details>`}
function bindPhone(){for(const [id,action]of [['phone-send','send'],['phone-check','check']])if($('#'+id))$('#'+id).onclick=async()=>{const b=$('#'+id);b.disabled=true;try{const r=await fetch('/api/phone',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,phone:$('#phone').value,code:$('#phone-code').value})});if(!r.ok)throw new Error();notice(w(action==='send'?'Kod gönderildi.':'Telefon doğrulandı.',action==='send'?'Code sent.':'Phone verified.'));if(action==='check'){await refresh();render()}}catch{notice(w('Doğrulama tamamlanamadı. Numara/kodu kontrol et veya biraz sonra dene.','Verification failed. Check the number/code or try again later.'))}finally{b.disabled=false}}}
const eventName=k=>({explanation_step:w('Tahtada anlatım adımı','Board explanation step'),guided_hint:w('Birlikte çözüm desteği','Guided solution support'),independent_test_started:w('Bağımsız test başladı','Independent test started'),board_note:w('Tahta notu kaydedildi','Board note saved'),lesson_review:w('Ders tekrarı','Lesson review'),assessment_started:w('Seviye belirleme başladı','Assessment started'),diagnostic_answer:w('Başlangıç sorusu cevaplandı','Assessment answer saved'),assessment_completed:w('Başlangıç haritası hazır','Assessment completed'),lesson_opened:w('Ders açıldı','Lesson opened'),answer:w('Soru cevaplandı','Question answered'),test_completed:w('Test tamamlandı','Test completed'),extra_test:w('Ek test başladı','Extra test started'),plan_saved:w('Çalışma planı kaydedildi','Study plan saved')})[k]||k;
function progress(){const passed=Object.values(state.units).filter(u=>u.passed).length,attempts=Object.values(state.units).flatMap(u=>u.attempts);layout(intro(w('Attığın her adım burada.','Every step lives here.'),w('Gerçek cevapların, testlerin ve çalışma geçmişin. İstersen seçtiğin kayıtları indirip öğretmenin veya velinle paylaşabilirsin.','Your answers, tests and activity history. Download selected records to share with your teacher or guardian.'))+`<div class="stats"><div class="stat"><b>${passed}/${topics.length}</b><span>${w('Tamamlanan konu','Topics completed')}</span></div><div class="stat"><b>${attempts.length}</b><span>${w('Tamamlanan test','Completed tests')}</span></div><div class="stat"><b>${state.activeMinutes}</b><span>${w('Etkin çalışma dakikası (yaklaşık)','Active study minutes (approx.)')}</span></div></div><div class="grid"><section class="card"><h2>${w('Başlangıçtan bugüne','From your starting point to today')}</h2>${state.diagnostic.done?`<div class="bars">${baseline(state).map(t=>{const u=state.units[t.id],score=u?.attempts.at(-1)?.score;return `<div class="bar-label"><span>${esc(t.title[lang])}</span><span>${t.score}% → <b>${score===undefined?w('henüz test yok','no test yet'):score+'%'}</b></span></div>`}).join('')}</div>`:`<p class="empty">${w('Başlangıç değerlendirmeni tamamlayınca karşılaştırman açılır.','Complete the starting assessment to see comparisons.')}</p>`}<p class="subtle">${w('Başlangıç soruları ve konu testleri farklı örneklemlerdir; karşılaştırma resmî ölçüm değildir.','Initial questions and topic tests use different samples; comparisons are not standardized measurements.')}</p></section><section class="card"><h2>${w('Paylaşmak istediğini seç','Choose what to share')}</h2><label class="check"><input type="checkbox" id="export-scores" checked>${w('Konu ve test sonuçları','Topic and test results')}</label><label class="check"><input type="checkbox" id="export-answers">${w('Cevaplarım ve açıklamalarım','My answers and reasoning')}</label><label class="check"><input type="checkbox" id="export-messages">${w('MOLİ konuşma dökümü','MOLİ conversation transcript')}</label><label class="check"><input type="checkbox" id="export-plan">${w('Çalışma planım','My study plan')}</label><div class="actions">${button(w('Raporu indir (.txt)','Download report (.txt)'),'export')}${button(w('Tam yedeği indir (.json)','Download full backup (.json)'),'backup',true)}</div><p class="subtle">${w('İndirme kimseye otomatik göndermez. Dosyayı seçtiğin kişiyle kendin paylaşabilirsin.','Downloading does not send records to anyone. Share the file with your chosen person yourself.')}</p></section></div><section class="card"><h2>${w('Son etkinliklerin','Recent activity')}</h2>${state.activity.length?[...state.activity].reverse().slice(0,50).map(a=>`<div class="timeline"><span>${eventName(a.kind)} ${a.topic?'· '+esc(title(a.topic)):''}${a.score!==undefined?' · '+a.score+'%':''}</span><time>${date(a.at)}</time></div>`).join(''):`<p class="empty">${w('İlk adımını bekliyoruz.','Your first step is waiting.')}</p>`}<p class="subtle">${w('Son 1.000 etkinlik ve son 600 konuşma mesajı tutulur.','The latest 1,000 activity events and 600 conversation messages are retained.')}</p></section>`);
 $('#export').onclick=()=>{const lines=['MOLİ · '+w('Öğrenme raporu','Learning report'),w('Görünen ad: ','Display name: ')+(user?.name||'Demo'),new Date().toISOString()];if($('#export-scores').checked){lines.push('\n'+w('BAŞLANGIÇ VE TEST SONUÇLARI','BASELINE AND TEST RESULTS'));for(const t of baseline(state))lines.push(title(t.id)+': '+w('Başlangıç ','Initial ')+(t.score??'—')+'%; '+(state.units[t.id]?.attempts.map(a=>date(a.at)+' '+a.score+'%').join(', ')||'—'))}if($('#export-answers').checked){lines.push('\n'+w('YANITLAR VE AÇIKLAMALAR (açıklamalar rubrikle puanlanmadı)','ANSWERS AND REASONING (reasoning not rubric graded)'));for(const a of [...state.diagnostic.answers,...Object.values(state.units).flatMap(u=>u.answers)])lines.push(`${a.id}: ${a.value} | ${a.reason||''} | ${a.correct?'✓':'–'}`)}if($('#export-answers').checked){lines.push('\n'+w('TAHTA NOTLARIM','MY BOARD NOTES'));for(const [id,u]of Object.entries(state.units))if(u.notes)lines.push(title(id)+': '+u.notes)}if($('#export-messages').checked){lines.push('\n'+w('KONUŞMALAR','CONVERSATIONS'));state.messages.forEach(m=>lines.push(`${date(m.at)} ${m.role}: ${m.text}`))}if($('#export-plan').checked)lines.push('\n'+JSON.stringify(state.plan,null,2));download('moli-rapor.txt',lines.join('\n'),'text/plain')};$('#backup').onclick=()=>download('moli-kayitlar.json',JSON.stringify({displayName:user?.name||'Demo',exportedAt:new Date().toISOString(),...state},null,2),'application/json');
}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){mic?.abort();if(!['discover','route','plan','progress'].includes(page))page='discover';prepare(state);({discover,route,plan,progress}[page])()}
async function start(){try{const demo=new URLSearchParams(location.search).get('demo')==='1';if(!demo){const r=await sessionRequest('session');if(!r.user){location.replace('/');return}user=r.user;if(user.role==='teacher'){location.replace('/teacher');return}lang=user.language||'tr'}else{try{lang=localStorage.getItem('moli.language')==='en'?'en':'tr'}catch{}}localKey='moli.learning.v1.'+(user?.id||'demo');if(demo){local=true}else{try{await refresh()}catch(e){if(e.message==='session_expired'){location.replace('/');return}if(e.message!=='learning_setup_required')throw e;local=true}}
 if(local){let saved;try{saved=JSON.parse(localStorage.getItem(localKey)||'null')}catch{}state=saved?.version===1?saved:initial();data=localView()}render();window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'discover';selected='';feedback=null;boardMode='lesson';revealed=0;stopSpeech();render();window.scrollTo(0,0)});let lastActivity=Date.now();for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>lastActivity=Date.now());setInterval(()=>{if(document.visibilityState==='visible'&&Date.now()-lastActivity<120000&&!busy&&!chatBusy)act('minutes')},60000);
 }catch{root.innerHTML=`<main class="loading"><h1>${w('Öğrenme alanına ulaşılamıyor.','Learning records are unavailable.')}</h1><p>${w('Bağlantı hatasında mevcut kayıtlarının üzerine yazmayız. Lütfen yeniden dene.','Your saved records are not overwritten when a connection fails. Please retry.')}</p><button class="button" onclick="location.reload()">${w('Yeniden dene','Try again')}</button></main>`}}
start();
